/// <summary>
///  designed from AVA
/// </summary>
/// <param name="args">args</param>
[PostHandlerFor(formStr(DocuView), formMethodStr(DocuView, close))]
public static void DocuView_Post_close(XppPrePostArgs args)
{
    FormRun   formRun = args.getThis();
  //  FormRun   callerFormRun = formRun.args().caller();



    if (formHasMethod(formRun,'actualTableId') && formHasMethod(FormRun,'actualRecId'))
    {
        TableId tableId = formRun.actualTableId();
        RecId   recId   = formRun.actualRecId();
        if (tableId  == tableNum(SalesQuotationLine))
        {
            SalesQuotationLine      salesQuotationLine = SalesQuotationLine::findRecId(recId);
            FormRun callerFormRun = formRun.args().caller();
            if (callerFormRun)
            {
                FormDataSource salesQuotationLineDS = callerFormRun.dataSource(tableStr(SalesQuotationLine));
                if(salesQuotationLineDS)
                {
                    salesQuotationLineDS.executeQuery();
                    salesQuotationLineDS.positionToRecord(salesQuotationLine);
                }
            }
        }
        if (tableId  == tableNum(SalesQuotationTable))
        {
            SalesQuotationTable      salesQuotationTable = SalesQuotationTable::findRec(recId);
            FormRun callerFormRun = formRun.args().caller();
            if (callerFormRun)
            {
                FormDataSource salesQuotationTableDS = callerFormRun.dataSource(tableStr(SalesQuotationTable));
                if(salesQuotationTableDS)
                {
                    salesQuotationTableDS.executeQuery();
                    salesQuotationTableDS.positionToRecord(salesQuotationTable);
                    salesQuotationTableDS.refresh();
                }
            }
        }
    }
}

/// <summary>
/// eventHandler method for OnClicked Event for Control AVATCVAdmin
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(DocuView, AVATCVAdmin), FormControlEventType::Clicked)]
public static void AVATCVAdmin_OnClicked(FormControl sender, FormControlEventArgs e)
{
    Args        args = new Args(formstr(AVATCVTable));
    FormRun		docuView = sender.formRun();
    DocuRef     docuRef = docuView.dataSource(formDataSourceStr(DocuView, DocuRef)).cursor();
    boolean     BPCheck;

    if(e)
    {
        BPCheck = true;
    }

    if(isConfigurationkeyEnabled(configurationKeyNum(AVATCV)))
    {
        args.record(docuRef);
        args.caller(docuView);
        if (docuRef.KCS_TCVIsLinked())
        {
            args.parm(docuRef.KCS_TCVId + '&&' + docuRef.KCS_TCVLanguageId);
            args.lookupRecord(KCS_TCVTable::find(docuRef.KCS_TCVId));
        }
        MenuFunction    menuFunction;
        menuFunction = new MenuFunction(menuitemDisplayStr(AVATCVTable), MenuItemType::Display);
        //menuFunction.run();
        menuFunction.run(args);
        /*fr = ClassFactory::formRunClassOnClient(args);
        fr.init();
        fr.run();
        fr.wait();
        FormDataUtil::getFormDataSource(docuRef).refresh();
        FormDataUtil::getFormDataSource(docuRef).research(true);
        docuView.setEnabled();
        docuView.KCS_TCVtoggleNotes(docuView);*/
    }


}

